import { NextResponse } from "next/server";
import { getRuntime } from "@/lib/runtime-instance";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Read model for the three-card board (UI polls this). Guarded by KKB_BOARD_KEY.
// Returns specialist cards only — never raw transcripts.
export async function GET(req: Request) {
  const url = new URL(req.url);
  if (!process.env.KKB_BOARD_KEY || url.searchParams.get("key") !== process.env.KKB_BOARD_KEY) {
    return NextResponse.json({ ok: false, error: "unauthorized" }, { status: 401 });
  }
  const rt = getRuntime();
  const convs = [...rt.conversations.values()];
  const conv = url.searchParams.get("callId") ? rt.conversations.get(url.searchParams.get("callId")!) : convs[convs.length - 1];
  return NextResponse.json({
    ok: true,
    snapshot: { label: rt.snapshot.label, repository: rt.snapshot.repository, pinnedSha: rt.snapshot.pinnedSha, fetchedAt: rt.snapshot.fetchedAt },
    conversation: conv ? { callId: conv.callId, focus: conv.focus, cards: conv.cards, turns: conv.turns, outstanding: conv.ledger.items.filter((i) => !i.acknowledged) } : null,
  });
}

import { NextResponse } from "next/server";
import { getRuntime } from "@/lib/runtime-instance";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Reports what is CONFIGURED, not what is proven. Proof lives in docs/plan.md.
export async function GET() {
  let snapshot: Record<string, unknown> = { loaded: false };
  try {
    const s = getRuntime().snapshot;
    snapshot = { loaded: true, label: s.label, repository: s.repository, pinnedSha: s.pinnedSha, fetchedAt: s.fetchedAt };
  } catch (e) {
    snapshot = { loaded: false, error: (e as Error).message };
  }
  return NextResponse.json({
    service: "kaam-ki-baat",
    snapshot,
    toolKeyConfigured: Boolean(process.env.KKB_TOOL_KEY),
    persistence: "append-only jsonl",
  });
}

import { NextResponse } from "next/server";
import { checkServerKey } from "@/lib/auth/call-session";
import { getRuntime } from "@/lib/runtime-instance";
import { runTool, TOOL_NAMES, type ToolName } from "@/lib/tools/runtime";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Bolna custom function endpoint: POST /api/tools/{get_my_brief|get_task_evidence|get_changes|record_task_update}
// Headers: Authorization: Bearer $KKB_TOOL_KEY. Body must include call_token (from Bolna user_data).
export async function POST(req: Request, ctx: { params: Promise<{ tool: string }> }) {
  const { tool } = await ctx.params;
  if (!TOOL_NAMES.includes(tool as ToolName)) return NextResponse.json({ ok: false, error: "unknown tool" }, { status: 404 });
  if (!checkServerKey(req.headers.get("authorization"), process.env.KKB_TOOL_KEY)) {
    return NextResponse.json({ ok: false, error: "unauthorized" }, { status: 401 });
  }
  let body: Record<string, unknown> = {};
  try { body = (await req.json()) as Record<string, unknown>; } catch { /* empty body */ }
  const res = await runTool(getRuntime(), tool as ToolName, body);
  return NextResponse.json(res.body, { status: res.status });
}

import type { ReactNode } from "react";

export const metadata = { title: "Kaam Ki Baat", description: "What was said. What was built. What was verified." };

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body style={{ margin: 0 }}>{children}</body>
    </html>
  );
}

"use client";
import { useEffect, useState } from "react";

// Three-card specialist board (left / center / right), Air Agents-style:
// the active specialist lights up; each card shows the evidence it returned.
// Visual metaphor only — the phone call itself is not spatial audio.

type Evidence = { id: string; label: string; url?: string; match?: "candidate" | "confirmed" };
type Card = { id: string; label: string; position: "left" | "center" | "right"; status: string; summary: string; evidence: Evidence[] };
type Board = {
  ok: boolean;
  error?: string;
  snapshot?: { label: string; repository: string; pinnedSha: string; fetchedAt: string };
  conversation: null | {
    callId: string;
    focus: { active: string; taskId: string | null; contextVersion: number };
    cards: Record<string, Card>;
    turns: { at: string; utterance: string; specialist: string; spoken: string }[];
    outstanding: { id: string; fact: string; attempts: number }[];
  };
};

const ORDER = ["code_scout", "fix_navigator", "evidence_verifier"];

export default function Home() {
  const [board, setBoard] = useState<Board | null>(null);
  useEffect(() => {
    const key = new URLSearchParams(window.location.search).get("key") ?? "";
    let alive = true;
    const tick = async () => {
      try {
        const r = await fetch(`/api/board?key=${encodeURIComponent(key)}`, { cache: "no-store" });
        const j = (await r.json()) as Board;
        if (alive) setBoard(j);
      } catch { /* keep last state */ }
    };
    tick();
    const t = setInterval(tick, 1500);
    return () => { alive = false; clearInterval(t); };
  }, []);

  const conv = board?.conversation;
  return (
    <main style={{ fontFamily: "ui-sans-serif, system-ui", background: "#0d0f12", color: "#e8e6e1", minHeight: "100vh", padding: "28px 32px" }}>
      <header style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 16, flexWrap: "wrap" }}>
        <div>
          <h1 style={{ margin: 0, fontSize: 28 }}>Kaam Ki Baat</h1>
          <p style={{ margin: "4px 0 0", opacity: 0.7 }}>Meeting mein bola. Repo mein bana?</p>
        </div>
        {board?.snapshot && (
          <div style={{ fontSize: 13, textAlign: "right" }}>
            <span style={{ padding: "2px 8px", borderRadius: 6, background: board.snapshot.label === "LIVE" ? "#1f6f43" : "#8a5a00", fontWeight: 600 }}>{board.snapshot.label}</span>{" "}
            {board.snapshot.repository} @ <code>{board.snapshot.pinnedSha.slice(0, 7)}</code>
            {conv && <div style={{ opacity: 0.7 }}>call {conv.callId} · task {conv.focus.taskId ?? "—"} · context v{conv.focus.contextVersion}</div>}
          </div>
        )}
      </header>

      {!board?.ok && <p style={{ marginTop: 32, opacity: 0.8 }}>{board?.error === "unauthorized" ? "Open this page with ?key=KKB_BOARD_KEY" : "Loading…"}</p>}
      {board?.ok && !conv && <p style={{ marginTop: 32, opacity: 0.8 }}>Waiting for a call. The board lights up when Bolna calls get_my_brief.</p>}

      {conv && (
        <>
          <section style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 18, marginTop: 28 }}>
            {ORDER.map((id) => {
              const c = conv.cards[id];
              const active = conv.focus.active === id;
              return (
                <article key={id} style={{
                  border: `1px solid ${active ? "#f0b429" : "#2a2f36"}`, borderRadius: 14, padding: 18, background: active ? "#1a1810" : "#14171b",
                  transform: active ? "translateY(-6px)" : "none", transition: "all .25s", boxShadow: active ? "0 10px 30px rgba(240,180,41,.15)" : "none",
                }}>
                  <div style={{ fontSize: 12, opacity: 0.6, textTransform: "uppercase", letterSpacing: 1 }}>{c.position}</div>
                  <h2 style={{ margin: "4px 0 6px", fontSize: 20 }}>{c.label}</h2>
                  <div style={{ fontSize: 12, marginBottom: 10, color: c.status === "error" ? "#ff6b6b" : active ? "#f0b429" : "#8b949e" }}>● {c.status.replace("_", " ")}</div>
                  <p style={{ fontSize: 14, lineHeight: 1.45, minHeight: 60 }}>{c.summary}</p>
                  <ul style={{ listStyle: "none", padding: 0, margin: 0, fontSize: 13 }}>
                    {c.evidence.map((e) => (
                      <li key={e.id} style={{ padding: "6px 0", borderTop: "1px solid #2a2f36" }}>
                        {e.match && <span style={{ fontSize: 11, marginRight: 6, padding: "1px 6px", borderRadius: 4, background: e.match === "confirmed" ? "#1f6f43" : "#444" }}>{e.match}</span>}
                        {e.url ? <a href={e.url} target="_blank" rel="noreferrer" style={{ color: "#79c0ff" }}>{e.label}</a> : e.label}
                      </li>
                    ))}
                  </ul>
                </article>
              );
            })}
          </section>
          <section style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 18, marginTop: 24 }}>
            <div style={{ background: "#14171b", borderRadius: 14, padding: 18 }}>
              <h3 style={{ marginTop: 0 }}>Conversation</h3>
              {conv.turns.slice(-6).map((t, i) => (
                <div key={i} style={{ fontSize: 14, marginBottom: 10 }}>
                  <div style={{ opacity: 0.7 }}>“{t.utterance || "…"}” → {t.specialist.replace("_", " ")}</div>
                  <div>{t.spoken}</div>
                </div>
              ))}
            </div>
            <div style={{ background: "#14171b", borderRadius: 14, padding: 18 }}>
              <h3 style={{ marginTop: 0 }}>Not yet acknowledged</h3>
              {conv.outstanding.length === 0 ? <p style={{ opacity: 0.7 }}>Everything was acknowledged.</p> :
                conv.outstanding.map((o) => <p key={o.id} style={{ fontSize: 14 }}>{o.fact} <span style={{ opacity: 0.6 }}>(said {o.attempts}×)</span></p>)}
            </div>
          </section>
        </>
      )}
    </main>
  );
}

import type { CheckRecord, PullRequestRecord } from "../contracts";

// Read-only GitHub REST adapter for ONE authorized repository.
// Token is optional for public repos (GITHUB_TOKEN raises rate limits).

export interface GitHubClient {
  pullRequest(number: number): Promise<PullRequestRecord>;
  checksFor(sha: string): Promise<CheckRecord[]>;
}

export function githubClient(repository: string, token = process.env.GITHUB_TOKEN, fetchImpl: typeof fetch = fetch): GitHubClient {
  if (!/^[^/]+\/[^/]+$/.test(repository)) throw new Error("repository must be owner/name");
  const get = async (p: string) => {
    const res = await fetchImpl(`https://api.github.com/repos/${repository}${p}`, {
      headers: { Accept: "application/vnd.github+json", "X-GitHub-Api-Version": "2022-11-28", ...(token ? { Authorization: `Bearer ${token}` } : {}) },
    });
    if (!res.ok) throw new Error(`GitHub ${p} -> ${res.status}`);
    return res.json() as Promise<any>;
  };
  return {
    async pullRequest(number) {
      const pr = await get(`/pulls/${number}`);
      const files: any[] = await get(`/pulls/${number}/files?per_page=100`);
      return {
        kind: "pr",
        id: `pr:${number}`,
        repository,
        number,
        title: pr.title,
        state: pr.merged_at ? "merged" : pr.state === "open" ? "open" : "closed_unmerged",
        headSha: pr.head.sha,
        mergedSha: pr.merge_commit_sha && pr.merged_at ? pr.merge_commit_sha : undefined,
        changedFiles: files.map((f) => f.filename),
        url: pr.html_url,
      };
    },
    async checksFor(sha) {
      const data = await get(`/commits/${sha}/check-runs?per_page=100`);
      return (data.check_runs as any[]).map((c) => ({
        kind: "check" as const,
        id: `check:${c.id}`,
        repository,
        commitSha: sha,
        name: c.name,
        conclusion: c.status !== "completed" ? "pending" : c.conclusion === "success" ? "success" : c.conclusion === "cancelled" ? "cancelled" : "failure",
        url: c.html_url,
      }));
    },
  };
}

import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
import type { EvidenceSnapshot, Participant } from "../contracts";
import type { CallSession, EventStore } from "../store/event-store";

// Identity is established server-side (D-009). The model never chooses who the
// caller is; Bolna only forwards the opaque per-call token we issued.

export const hashToken = (t: string) => createHash("sha256").update(t).digest("hex");

export async function issueCallSession(
  store: EventStore,
  input: Omit<CallSession, "callId" | "tokenHash" | "expiresAt"> & { ttlMinutes?: number },
): Promise<{ token: string; session: CallSession }> {
  const token = randomBytes(24).toString("base64url");
  const session: CallSession = {
    callId: `call_${randomBytes(6).toString("hex")}`,
    tokenHash: hashToken(token),
    participantId: input.participantId,
    meetingIds: input.meetingIds,
    repository: input.repository,
    consentRecordedBy: input.consentRecordedBy,
    scenario: input.scenario,
    expiresAt: new Date(Date.now() + (input.ttlMinutes ?? 60) * 60_000).toISOString(),
  };
  await store.append({ type: "call_session", at: new Date().toISOString(), session });
  return { token, session };
}

export interface Caller {
  session: CallSession;
  participant: Participant;
  taskIds: ReadonlySet<string>;
}

export type AuthResult = { ok: true; caller: Caller } | { ok: false; status: 401 | 403; reason: string };

/** Server key check for every runtime tool request (Authorization: Bearer). */
export function checkServerKey(header: string | null, expected: string | undefined): boolean {
  if (!expected || !header?.startsWith("Bearer ")) return false;
  const a = Buffer.from(header.slice(7));
  const b = Buffer.from(expected);
  return a.length === b.length && timingSafeEqual(a, b);
}

export async function resolveCaller(
  store: EventStore,
  snapshot: EvidenceSnapshot,
  token: unknown,
  now = new Date(),
): Promise<AuthResult> {
  if (typeof token !== "string" || token.length < 16) return { ok: false, status: 401, reason: "missing call token" };
  const session = await store.findCallByTokenHash(hashToken(token));
  if (!session) return { ok: false, status: 401, reason: "unknown call token" };
  if (new Date(session.expiresAt) < now) return { ok: false, status: 401, reason: "call token expired" };
  if (!session.consentRecordedBy) return { ok: false, status: 403, reason: "no consent recorded" };
  if (session.repository !== snapshot.repository) return { ok: false, status: 403, reason: "repository not authorized for this call" };
  const participant = snapshot.participants.find((p) => p.id === session.participantId);
  if (!participant) return { ok: false, status: 403, reason: "participant not in authorized snapshot" };
  // A task is visible only if the participant holds it AND its meeting is authorized for both the call and the person.
  const taskIds = new Set(
    snapshot.tasks
      .filter((t) => participant.taskIds.includes(t.id))
      .filter((t) => session.meetingIds.includes(t.meetingId) && participant.meetingIds.includes(t.meetingId))
      .map((t) => t.id),
  );
  return { ok: true, caller: { session, participant, taskIds } };
}

// Shared data contracts. Pure TypeScript, no runtime dependencies, so the
// domain core runs and tests anywhere (Node + tsx). Validate at the HTTP edge
// with the hand-written guards in lib/validate.ts.
//
// Evidence is SOURCE DATA, never instructions. Every code/check claim is pinned
// to a commit SHA. Status vocabulary follows docs/architecture.md §5.

export type SourceLabel = "LIVE" | "FIXTURE";

export type OwnershipState = "mentioned" | "proposed" | "accepted" | "disputed" | "unknown";
export type PrState = "none" | "open" | "closed_unmerged" | "merged";
export type CheckConclusion = "success" | "failure" | "pending" | "cancelled";
export type CheckState = "not_run" | "pending" | "passed" | "failed" | "stale";
export type CompletionStatus = "not_started" | "in_progress" | "blocked" | "reported_done";

export interface MeetingRecord {
  id: string; // Wispr meeting ID
  title: string;
  date?: string;
  source: SourceLabel; // LIVE = read through Wispr MCP for an approved meeting
  approvedBy: string; // who approved this meeting for the project
}

export interface MeetingPassage {
  kind: "meeting";
  id: string;
  meetingId: string;
  speaker?: string;
  charStart: number;
  charEnd: number;
  text: string;
  visibility: "participant" | "team";
}

export interface RepoFile {
  path: string;
  content: string; // file content at snapshot.pinnedSha
}

export interface PullRequestRecord {
  kind: "pr";
  id: string;
  repository: string;
  number: number;
  title: string;
  state: Exclude<PrState, "none">;
  headSha: string;
  mergedSha?: string;
  changedFiles: string[];
  url: string;
}

export interface CheckRecord {
  kind: "check";
  id: string;
  repository: string;
  commitSha: string;
  name: string;
  conclusion: CheckConclusion;
  url?: string;
}

export interface CodeFinding {
  kind: "code";
  id: string;
  repository: string;
  commitSha: string;
  path: string;
  lineStart: number;
  lineEnd: number;
  symbol?: string;
  excerpt: string;
  // confirmed = file is changed by the task's PR AND matches; otherwise candidate.
  match: "candidate" | "confirmed";
  url: string;
}

export interface Task {
  id: string;
  title: string;
  meetingId: string;
  passageIds: string[];
  assignment: { state: OwnershipState; ownerId?: string };
  prNumber?: number;
  searchTerms: string[]; // deterministic seeds for Code Scout
}

export interface Participant {
  id: string;
  name: string;
  meetingIds: string[]; // meetings this person may hear about
  taskIds: string[]; // tasks this person may read/update
}

export interface EvidenceSnapshot {
  label: SourceLabel;
  note?: string;
  repository: string; // owner/name
  pinnedSha: string;
  fetchedAt: string;
  meetings: MeetingRecord[];
  passages: MeetingPassage[];
  files: RepoFile[];
  pullRequests: PullRequestRecord[];
  checks: CheckRecord[];
  tasks: Task[];
  participants: Participant[];
}

export interface TaskUpdateRequest {
  taskId: string;
  intendedStatus: CompletionStatus;
  confirmation: true;
  idempotencyKey: string;
}

// Attempted speech is NOT proof that the listener heard it.
export type ReportItem={id:string;fact:string;attempts:number;acknowledged:boolean};
export type Report={callId:string;items:ReportItem[];interrupted:boolean};
export function newReport(callId:string,facts:{id:string;fact:string}[]):Report{
 if(new Set(facts.map(f=>f.id)).size!==facts.length)throw new Error("duplicate fact");
 return {callId,items:facts.map(f=>({...f,attempts:0,acknowledged:false})),interrupted:false};
}
export function markAttempted(r:Report,id:string):Report{
 if(!r.items.some(i=>i.id===id))throw new Error("unknown fact");
 return {...r,items:r.items.map(i=>i.id===id?{...i,attempts:i.attempts+1}:i)};
}
export function confirmHeard(r:Report,id:string):Report{
 if(!r.items.some(i=>i.id===id&&i.attempts>0))throw new Error("cannot confirm unattempted fact");
 return {...r,items:r.items.map(i=>i.id===id?{...i,acknowledged:true}:i)};
}
export function markInterrupted(r:Report):Report{return {...r,interrupted:true}}
export function outstandingFacts(r:Report):ReportItem[]{return r.items.filter(i=>!i.acknowledged)}

import type { CompletionStatus } from "../contracts";
import { parseTaskUpdate } from "../validate";

// Caller identity is trusted only when supplied by server authentication, never from LLM arguments.
export interface SavedUpdate {
  id: string;
  taskId: string;
  actorId: string;
  callId: string | null;
  status: CompletionStatus;
  idempotencyKey: string;
  at: string;
}

export interface UpdateRepository {
  /** Returns the existing record when the idempotency key was already used. */
  writeOnce(record: SavedUpdate): Promise<{ id: string; replayed: boolean }>;
  read(id: string): Promise<SavedUpdate | null>;
}

export type PersistResult =
  | { saved: true; recordId: string; replayed: boolean; readBack: SavedUpdate }
  | { saved: false; reason: string };

export async function persistVerifiedUpdate(args: {
  raw: unknown;
  trustedActorId: string | null;
  callId?: string | null;
  authorizedTaskIds: ReadonlySet<string>;
  blockedTaskIds?: ReadonlyMap<string, string>; // taskId -> reason (e.g. disputed ownership)
  repository: UpdateRepository;
  generateId: () => string;
  now?: () => string;
  timeoutMs?: number;
}): Promise<PersistResult> {
  const parsed = parseTaskUpdate(args.raw);
  if (!parsed.ok) return { saved: false, reason: `invalid or unconfirmed update: ${parsed.reason}` };
  const req = parsed.value;
  if (!args.trustedActorId || !args.authorizedTaskIds.has(req.taskId)) return { saved: false, reason: "unauthorized" };
  const blocked = args.blockedTaskIds?.get(req.taskId);
  if (blocked) return { saved: false, reason: blocked };

  const candidate: SavedUpdate = {
    id: args.generateId(),
    taskId: req.taskId,
    actorId: args.trustedActorId,
    callId: args.callId ?? null,
    status: req.intendedStatus,
    idempotencyKey: req.idempotencyKey,
    at: (args.now ?? (() => new Date().toISOString()))(),
  };
  try {
    const written = await withTimeout(args.repository.writeOnce(candidate), args.timeoutMs ?? 3000);
    const actual = await withTimeout(args.repository.read(written.id), args.timeoutMs ?? 3000);
    if (!actual) return { saved: false, reason: "read-back failed: record not found" };
    const same =
      actual.taskId === candidate.taskId &&
      actual.actorId === candidate.actorId &&
      actual.status === candidate.status &&
      actual.idempotencyKey === candidate.idempotencyKey;
    if (!same) {
      return {
        saved: false,
        reason: written.replayed ? "idempotency key was already used for a different update" : "read-back failed: mismatch",
      };
    }
    return { saved: true, recordId: actual.id, replayed: written.replayed, readBack: actual };
  } catch {
    return { saved: false, reason: "write failed or timed out" };
  }
}

function withTimeout<T>(p: Promise<T>, ms: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error("timeout")), ms);
    p.then((v) => { clearTimeout(t); resolve(v); }, (e) => { clearTimeout(t); reject(e); });
  });
}

import type { CheckRecord, CheckState, OwnershipState, PrState, PullRequestRecord, Task } from "../contracts";

// Deterministic status rules. The ONLY place status is decided. No LLM here.
export interface Reconciled {
  taskId: string;
  ownership: OwnershipState;
  acceptedOwnerId: string | null;
  pr: PrState;
  prNumber: number | null;
  currentSha: string | null; // head SHA for open PRs, merged SHA for merged PRs
  checks: CheckState;
  checkShaSeen: string | null; // SHA the latest available check ran on
  productionVerified: false; // never derivable from CI
  warnings: string[];
}

export function reconcileTask(task: Task, prs: PullRequestRecord[], checks: CheckRecord[]): Reconciled {
  const warnings: string[] = [];
  const pr = task.prNumber != null ? prs.find((p) => p.number === task.prNumber) : undefined;
  if (task.prNumber != null && !pr) warnings.push(`PR #${task.prNumber} is referenced but was not found in the snapshot`);

  const acceptedOwnerId = task.assignment.state === "accepted" ? task.assignment.ownerId ?? null : null;
  if (task.assignment.state === "accepted" && !acceptedOwnerId) warnings.push("accepted ownership has no confirmed person");
  if (task.assignment.state === "mentioned") warnings.push("owner was only mentioned, not assigned");
  if (task.assignment.state === "proposed") warnings.push("owner was proposed but has not accepted");
  if (task.assignment.state === "disputed") warnings.push("ownership is disputed");

  const prState: PrState = pr ? pr.state : "none";
  if (pr?.state === "open") warnings.push(`PR #${pr.number} is open, not merged`);
  if (pr?.state === "merged" && !pr.mergedSha) warnings.push("merged PR has no merged commit SHA");
  const currentSha = pr ? (pr.state === "merged" ? pr.mergedSha ?? null : pr.headSha) : null;

  let checkState: CheckState = "not_run";
  let checkShaSeen: string | null = null;
  if (pr) {
    const related = checks.filter((c) => c.repository === pr.repository);
    const onCurrent = currentSha ? related.filter((c) => c.commitSha === currentSha) : [];
    if (onCurrent.length) {
      checkShaSeen = currentSha;
      checkState = onCurrent.some((c) => c.conclusion === "failure" || c.conclusion === "cancelled")
        ? "failed"
        : onCurrent.every((c) => c.conclusion === "success")
          ? "passed"
          : "pending";
    } else if (related.length) {
      checkShaSeen = related[related.length - 1].commitSha;
      checkState = "stale";
      warnings.push(`latest check ran on ${short(checkShaSeen)}, not the current ${short(currentSha)}`);
    }
  }

  return {
    taskId: task.id,
    ownership: task.assignment.state,
    acceptedOwnerId,
    pr: prState,
    prNumber: pr?.number ?? null,
    currentSha,
    checks: checkState,
    checkShaSeen,
    productionVerified: false,
    warnings,
  };
}

export function short(sha: string | null | undefined): string {
  return sha ? sha.slice(0, 7) : "unknown";
}

// Air Agents-inspired focus switching (github.com/ahmedfahim21/Spatial-Agents):
// each agent has a fixed place (azimuth), a visible status, and keeps its own
// context. Here the "place" is a card position in the UI. This is NOT
// head-tracked spatial audio — a phone call is mono.
export type Specialist = "code_scout" | "fix_navigator" | "evidence_verifier";
export type CardStatus = "idle" | "working" | "has_reply" | "needs_approval" | "error";

export interface FocusState {
  active: Specialist;
  taskId: string | null;
  contextVersion: number;
}

export const SPECIALISTS: Record<Specialist, { label: string; purpose: string; position: "left" | "center" | "right"; readOnly: true }> = {
  code_scout: { label: "Code Scout", purpose: "Find the relevant code, PRs and history at a pinned SHA", position: "left", readOnly: true },
  fix_navigator: { label: "Fix Navigator", purpose: "Exact file, function, test and next steps", position: "center", readOnly: true },
  evidence_verifier: { label: "Evidence Verifier", purpose: "What is actually merged, tested and saved", position: "right", readOnly: true },
};

export function chooseSpecialist(utterance: string, current: Specialist = "code_scout"): Specialist {
  const s = utterance.toLowerCase();
  if (/\b(where|which file|how do i fix|show me the code|which function|line|kahan|kis file|kaunsa function|open)\b/.test(s)) return "fix_navigator";
  if (/\b(proof|evidence|verified|tests? pass|passed|ci|is it done|done|merged|merge|source|really finished|saved|ho gaya)\b/.test(s)) return "evidence_verifier";
  if (/\b(find|what changed|what is left|what's left|pull request|pr|issue|search|what happened|kya bacha)\b/.test(s)) return "code_scout";
  return current;
}

/** Switching focus never drops the task or bumps the context version. */
export function switchFocus(state: FocusState, next: Specialist): FocusState {
  return { ...state, active: next };
}

import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import type { EvidenceSnapshot } from "../contracts";

// Live snapshot (private, gitignored) wins; otherwise the clearly labeled fixture.
export const PRIVATE_SNAPSHOT = "data/private/snapshot.json";
export const FIXTURE_SNAPSHOT = "data/demo/snapshot.fixture.json";

export function loadSnapshot(root = process.cwd()): EvidenceSnapshot {
  const explicit = process.env.KKB_SNAPSHOT;
  const candidates = explicit ? [explicit] : [PRIVATE_SNAPSHOT, FIXTURE_SNAPSHOT];
  for (const rel of candidates) {
    const p = path.resolve(root, rel);
    if (existsSync(p)) return JSON.parse(readFileSync(p, "utf8")) as EvidenceSnapshot;
  }
  throw new Error(`No evidence snapshot found. Run: npm run snapshot (looked in ${candidates.join(", ")})`);
}

import path from "node:path";
import { EventStore } from "./store/event-store";
import { loadSnapshot } from "./evidence/load";
import type { Runtime } from "./tools/runtime";

// One process-wide runtime for the Next.js server. Conversations live in memory
// (single process); every write and tool call is persisted in the event log.
const g = globalThis as unknown as { __kkbRuntime?: Runtime };

export function getRuntime(): Runtime {
  if (!g.__kkbRuntime) {
    g.__kkbRuntime = {
      store: new EventStore(path.resolve(process.env.KKB_EVENTS_FILE ?? "data/runtime/events.jsonl")),
      snapshot: loadSnapshot(),
      conversations: new Map(),
    };
  }
  return g.__kkbRuntime;
}

import type { CodeFinding, EvidenceSnapshot, Task } from "../contracts";

// Agent A — Code Scout: find relevant code at the pinned SHA. No indexing, no
// embeddings (D-017): a bounded keyword scan of the snapshot's files.
// A hit is "confirmed" only when the file is also changed by the task's PR;
// a keyword-only hit stays a "candidate".

const STOP = new Set(["the", "a", "an", "is", "it", "to", "of", "and", "or", "for", "in", "on", "where", "which", "what", "how", "me", "my", "code", "file", "kahan", "hai", "ka", "ki", "ke", "show", "find", "this", "that", "do", "i"]);

export function queryTerms(task: Task | undefined, utterance: string): string[] {
  const fromUtterance = utterance
    .toLowerCase()
    .split(/[^a-z0-9_-]+/)
    .filter((w) => w.length > 3 && !STOP.has(w));
  return [...new Set([...(task?.searchTerms ?? []).map((t) => t.toLowerCase()), ...fromUtterance])];
}

export function codeScout(snapshot: EvidenceSnapshot, task: Task | undefined, utterance: string, limit = 3): CodeFinding[] {
  const terms = queryTerms(task, utterance);
  if (!terms.length) return [];
  const pr = task?.prNumber != null ? snapshot.pullRequests.find((p) => p.number === task.prNumber) : undefined;
  const changed = new Set(pr?.changedFiles ?? []);

  const scored: Array<CodeFinding & { score: number }> = [];
  for (const file of snapshot.files) {
    const lines = file.content.split("\n");
    let best = { line: -1, score: 0 };
    lines.forEach((text, i) => {
      const lower = text.toLowerCase();
      const s = terms.reduce((acc, t) => acc + (lower.includes(t) ? 1 : 0), 0);
      // prefer definitions over mentions
      const bonus = /\b(function|class|interface|const|export)\b/.test(text) ? 0.5 : 0;
      if (s > 0 && s + bonus > best.score) best = { line: i, score: s + bonus };
    });
    if (best.line < 0) continue;
    const pathBonus = terms.some((t) => file.path.toLowerCase().includes(t)) ? 1 : 0;
    const isTest = /(^|\/)tests?\//.test(file.path) || /\.test\./.test(file.path);
    const symbol = enclosingSymbol(lines, best.line);
    const start = Math.max(1, best.line + 1 - 1);
    const end = Math.min(lines.length, best.line + 1 + 2);
    scored.push({
      kind: "code",
      id: `code:${snapshot.pinnedSha.slice(0, 7)}:${file.path}:${best.line + 1}`,
      repository: snapshot.repository,
      commitSha: snapshot.pinnedSha,
      path: file.path,
      lineStart: start,
      lineEnd: end,
      symbol,
      excerpt: lines.slice(start - 1, end).join("\n").slice(0, 400),
      match: changed.has(file.path) ? "confirmed" : "candidate",
      url: permalink(snapshot.repository, snapshot.pinnedSha, file.path, start, end),
      score: best.score + pathBonus + (changed.has(file.path) ? 1 : 0) - (isTest ? 0.75 : 0),
    });
  }
  return scored
    .sort((a, b) => b.score - a.score || a.path.localeCompare(b.path))
    .slice(0, limit)
    .map(({ score: _s, ...f }) => f);
}

export function enclosingSymbol(lines: string[], from: number): string | undefined {
  const re = /(?:export\s+)?(?:async\s+)?(?:function\s+([A-Za-z0-9_]+)|(?:const|let)\s+([A-Za-z0-9_]+)\s*=|class\s+([A-Za-z0-9_]+)|interface\s+([A-Za-z0-9_]+))/;
  for (let i = from; i >= 0 && i > from - 80; i--) {
    const m = lines[i].match(re);
    if (m) return m[1] ?? m[2] ?? m[3] ?? m[4];
  }
  return undefined;
}

export const permalink = (repo: string, sha: string, path: string, a: number, b: number) =>
  `https://github.com/${repo}/blob/${sha}/${path}#L${a}-L${b}`;

import type { EvidenceSnapshot, Task } from "../contracts";
import { reconcileTask, short, type Reconciled } from "../core/reconcile";
import type { SavedUpdate } from "../core/persist-update";

// Agent C — Evidence Verifier: what is genuinely supported. Deterministic.

export interface Verdict {
  reconciled: Reconciled;
  lastSavedUpdate: SavedUpdate | null;
  canSayDone: boolean; // only true with merged PR + passing check on the merged SHA
  statements: string[]; // short, speakable, each one evidence-backed
}

export function evidenceVerifier(snapshot: EvidenceSnapshot, task: Task, lastSavedUpdate: SavedUpdate | null): Verdict {
  const r = reconcileTask(task, snapshot.pullRequests, snapshot.checks);
  const s: string[] = [];
  if (r.pr === "none") s.push("There's no pull request linked to this yet.");
  if (r.pr === "open") s.push(`PR #${r.prNumber} exists but it's still open — not merged.`);
  if (r.pr === "closed_unmerged") s.push(`PR #${r.prNumber} was closed without merging.`);
  if (r.pr === "merged") s.push(`PR #${r.prNumber} is merged at ${short(r.currentSha)}.`);

  if (r.checks === "passed") s.push(`Checks passed on the current commit ${short(r.currentSha)}. That's CI, not proof it works in production.`);
  if (r.checks === "failed") s.push(`Checks failed on the current commit ${short(r.currentSha)}.`);
  if (r.checks === "pending") s.push(`Checks are still running on ${short(r.currentSha)}.`);
  if (r.checks === "stale") s.push(`The last check result is for an older commit, ${short(r.checkShaSeen)}, so it doesn't verify the current code.`);
  if (r.checks === "not_run" && r.pr !== "none") s.push("No CI result exists for this commit.");

  if (r.ownership !== "accepted") s.push(ownershipLine(r.ownership));
  if (lastSavedUpdate) s.push(`Last saved update: ${lastSavedUpdate.status.replace("_", " ")} (record ${lastSavedUpdate.id}).`);

  const canSayDone = r.pr === "merged" && r.checks === "passed";
  return { reconciled: r, lastSavedUpdate, canSayDone, statements: s };
}

function ownershipLine(state: Reconciled["ownership"]): string {
  switch (state) {
    case "mentioned": return "Your name came up, but nobody actually assigned this.";
    case "proposed": return "This was proposed for you; you haven't accepted it yet.";
    case "disputed": return "Ownership of this is disputed.";
    default: return "Ownership isn't established.";
  }
}

import type { CodeFinding, EvidenceSnapshot } from "../contracts";
import { enclosingSymbol, permalink } from "./code-scout";

// Agent B — Fix Navigator: turn Code Scout's findings into "open this, check
// that, run this test". Read-only: it never edits code (handoff §3, Agent B).

export interface NavigationPlan {
  target: CodeFinding | null;
  test: { path: string; line: number; url: string } | null;
  steps: string[];
  spoken: string;
}

export function fixNavigator(snapshot: EvidenceSnapshot, findings: CodeFinding[]): NavigationPlan {
  const target = findings.find((f) => !isTestPath(f.path)) ?? findings[0] ?? null;
  if (!target) {
    return { target: null, test: null, steps: [], spoken: "I couldn't find a matching file at the pinned commit. Tell me a function or file name and I'll look again." };
  }
  const test = findTest(snapshot, target);
  const fn = target.symbol ? `the ${target.symbol} function` : `line ${target.lineStart}`;
  const steps = [
    `Open ${target.path} at line ${target.lineStart} (${fn}) — commit ${target.commitSha.slice(0, 7)}.`,
    test ? `Read the regression test in ${test.path} around line ${test.line}.` : "No nearby test found — add one before changing behaviour.",
    test ? `Run: npm test -- ${test.path}` : "Run: npm test",
  ];
  const certainty = target.match === "confirmed" ? "This file is part of the PR." : "This is a likely match, not confirmed by the PR.";
  const spoken =
    `Open ${spokenPath(target.path)}, ${fn}, around line ${target.lineStart}. ${certainty}` +
    (test ? ` Then check the test in ${spokenPath(test.path)}.` : " There's no test next to it yet.");
  return { target, test, steps, spoken };
}

function findTest(snapshot: EvidenceSnapshot, target: CodeFinding) {
  const base = target.path.split("/").pop()!.replace(/\.[tj]sx?$/, "");
  for (const f of snapshot.files) {
    if (!isTestPath(f.path)) continue;
    const lines = f.content.split("\n");
    const idx = lines.findIndex((l) => (target.symbol && l.includes(target.symbol)) || l.includes(`/${base}"`) || l.includes(`/${base}'`));
    if (idx >= 0) {
      const sym = enclosingSymbol(lines, idx);
      void sym;
      return { path: f.path, line: idx + 1, url: permalink(snapshot.repository, snapshot.pinnedSha, f.path, idx + 1, idx + 1) };
    }
  }
  return null;
}

const isTestPath = (p: string) => /(^|\/)tests?\//.test(p) || /\.test\./.test(p);
// "lib/core/persist-update.ts" -> "persist-update dot ts in lib core" reads better on a call
const spokenPath = (p: string) => {
  const parts = p.split("/");
  const file = parts.pop()!;
  return parts.length ? `${file} in ${parts.join(" ")}` : file;
};

import type { CodeFinding, EvidenceSnapshot, Task } from "../contracts";
import { confirmHeard, markAttempted, newReport, outstandingFacts, type Report } from "../core/communication-ledger";
import type { SavedUpdate } from "../core/persist-update";
import { chooseSpecialist, SPECIALISTS, switchFocus, type CardStatus, type FocusState, type Specialist } from "../core/spatial-specialists";
import { codeScout } from "./code-scout";
import { evidenceVerifier } from "./evidence-verifier";
import { fixNavigator, type NavigationPlan } from "./fix-navigator";

// One voice persona, three specialists behind it. Shared state (taskId,
// contextVersion, evidence) survives every switch so the caller never repeats
// themselves. The communication ledger keeps unfinished facts across interruptions.

export interface Card {
  id: Specialist;
  label: string;
  position: "left" | "center" | "right";
  status: CardStatus;
  summary: string;
  evidence: Array<{ id: string; label: string; url?: string; match?: "candidate" | "confirmed" }>;
}

export interface Conversation {
  callId: string;
  participantId: string;
  focus: FocusState;
  cards: Record<Specialist, Card>;
  ledger: Report;
  findings: CodeFinding[]; // Code Scout's latest results, reused by Fix Navigator
  lastSpokenFactIds: string[];
  turns: Array<{ at: string; utterance: string; specialist: Specialist; spoken: string }>;
}

export function startConversation(callId: string, participantId: string, taskId: string | null, briefFacts: { id: string; fact: string }[]): Conversation {
  const cards = Object.fromEntries(
    (Object.keys(SPECIALISTS) as Specialist[]).map((id) => [
      id,
      { id, label: SPECIALISTS[id].label, position: SPECIALISTS[id].position, status: "idle" as CardStatus, summary: SPECIALISTS[id].purpose, evidence: [] },
    ]),
  ) as unknown as Record<Specialist, Card>;
  return {
    callId,
    participantId,
    focus: { active: "evidence_verifier", taskId, contextVersion: 1 },
    cards,
    ledger: newReport(callId, briefFacts),
    findings: [],
    lastSpokenFactIds: [],
    turns: [],
  };
}

const ACK = /\b(ok|okay|got it|understood|samajh gaya|samajh gayi|theek hai|thik hai|haan|yes|right|clear)\b/i;

export interface TurnResult {
  conversation: Conversation;
  specialist: Specialist;
  spoken: string;
  resumedFactIds: string[];
  navigation?: NavigationPlan;
}

export function handleTurn(
  conv: Conversation,
  snapshot: EvidenceSnapshot,
  task: Task | undefined,
  lastSaved: SavedUpdate | null,
  input: { utterance: string; focus?: Specialist },
): TurnResult {
  let c: Conversation = { ...conv, cards: { ...conv.cards } };

  // Acknowledgement of what we just said is the only proof it was heard.
  if (ACK.test(input.utterance)) {
    for (const id of c.lastSpokenFactIds) {
      try { c.ledger = confirmHeard(c.ledger, id); } catch { /* not attempted yet */ }
    }
  }

  const specialist = input.focus ?? chooseSpecialist(input.utterance, c.focus.active);
  c.focus = switchFocus(c.focus, specialist);
  for (const id of Object.keys(c.cards) as Specialist[]) {
    c.cards[id] = { ...c.cards[id], status: id === specialist ? "working" : c.cards[id].status === "working" ? "idle" : c.cards[id].status };
  }

  let spoken = "";
  let navigation: NavigationPlan | undefined;
  if (specialist === "code_scout") {
    const findings = codeScout(snapshot, task, input.utterance);
    c.findings = findings;
    spoken = findings.length
      ? `I found ${findings.length} place${findings.length > 1 ? "s" : ""}. The best match is ${findings[0].path}${findings[0].symbol ? `, in ${findings[0].symbol}` : ""} — ${findings[0].match === "confirmed" ? "it's changed in the PR" : "a possible match, not confirmed"}.`
      : "I didn't find a match at the pinned commit.";
    c.cards.code_scout = { ...c.cards.code_scout, status: "has_reply", summary: spoken, evidence: findings.map(cardEvidence) };
  } else if (specialist === "fix_navigator") {
    if (!c.findings.length) c.findings = codeScout(snapshot, task, input.utterance); // reuse context, don't make the caller repeat
    navigation = fixNavigator(snapshot, c.findings);
    spoken = navigation.spoken;
    c.cards.fix_navigator = {
      ...c.cards.fix_navigator,
      status: "has_reply",
      summary: navigation.steps.join(" "),
      evidence: [
        ...(navigation.target ? [cardEvidence(navigation.target)] : []),
        ...(navigation.test ? [{ id: `test:${navigation.test.path}`, label: `${navigation.test.path}:${navigation.test.line}`, url: navigation.test.url }] : []),
      ],
    };
    if (c.findings.length && !c.cards.code_scout.evidence.length) {
      c.cards.code_scout = { ...c.cards.code_scout, status: "has_reply", evidence: c.findings.map(cardEvidence) };
    }
  } else {
    if (!task) {
      spoken = "I don't have a task you're authorized for, so I can't verify anything.";
    } else {
      const v = evidenceVerifier(snapshot, task, lastSaved);
      spoken = v.statements.slice(0, 3).join(" ");
      c.cards.evidence_verifier = {
        ...c.cards.evidence_verifier,
        status: "has_reply",
        summary: v.statements.join(" "),
        evidence: [
          ...snapshot.pullRequests.filter((p) => p.number === task.prNumber).map((p) => ({ id: p.id, label: `PR #${p.number} · ${p.state} · ${p.headSha.slice(0, 7)}`, url: p.url })),
          ...snapshot.checks.filter((k) => k.commitSha === v.reconciled.currentSha || k.commitSha === v.reconciled.checkShaSeen).map((k) => ({ id: k.id, label: `${k.name}: ${k.conclusion} @ ${k.commitSha.slice(0, 7)}`, url: k.url })),
          ...(lastSaved ? [{ id: lastSaved.id, label: `saved: ${lastSaved.status}` }] : []),
        ],
      };
    }
  }

  // Interruption recovery: answer first, then return to ONE important unfinished fact.
  // A fact gets its first attempt in the brief and at most one recovery attempt.
  const pending = outstandingFacts(c.ledger).filter((f) => f.attempts < 2);
  const resumed = pending.slice(0, 1);
  if (resumed.length) {
    spoken += ` Also, before I forget: ${resumed[0].fact}`;
    c.ledger = markAttempted(c.ledger, resumed[0].id);
  }
  c.lastSpokenFactIds = resumed.map((f) => f.id);
  c.turns = [...c.turns, { at: new Date().toISOString(), utterance: input.utterance, specialist, spoken }];
  return { conversation: c, specialist, spoken, resumedFactIds: resumed.map((f) => f.id), navigation };
}

const cardEvidence = (f: CodeFinding) => ({
  id: f.id,
  label: `${f.path}:${f.lineStart}${f.symbol ? ` (${f.symbol})` : ""} @ ${f.commitSha.slice(0, 7)}`,
  url: f.url,
  match: f.match,
});

import { promises as fs } from "node:fs";
import path from "node:path";
import type { SavedUpdate, UpdateRepository } from "../core/persist-update";

// Append-only event log (D-011). One JSON object per line. Old values are never
// overwritten. Pass file=null for an in-memory store (tests).

export type StoredEvent =
  | { type: "task_update"; at: string; record: SavedUpdate }
  | { type: "call_session"; at: string; session: CallSession }
  | { type: "tool_call"; at: string; callId: string; tool: string; ok: boolean; summary: string; evidenceIds: string[] }
  | { type: "communicated"; at: string; callId: string; factId: string; fact: string; acknowledged: boolean };

export interface CallSession {
  callId: string;
  tokenHash: string; // sha256 of the per-call token; the raw token is never stored
  participantId: string;
  meetingIds: string[];
  repository: string;
  consentRecordedBy: string; // who recorded consent, and how (free text, no phone numbers)
  scenario: string;
  expiresAt: string;
}

export class EventStore implements UpdateRepository {
  private events: StoredEvent[] | null = null;
  private chain: Promise<unknown> = Promise.resolve();

  constructor(private readonly file: string | null) {}

  async all(): Promise<StoredEvent[]> {
    if (this.events) return this.events;
    if (!this.file) return (this.events = []);
    try {
      const raw = await fs.readFile(this.file, "utf8");
      this.events = raw.split("\n").filter(Boolean).map((l) => JSON.parse(l) as StoredEvent);
    } catch (e: unknown) {
      if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e;
      this.events = [];
    }
    return this.events;
  }

  /** Serialized, durable append. Resolves only after the line is fsynced. */
  append(event: StoredEvent): Promise<void> {
    const run = async () => {
      const events = await this.all();
      if (this.file) {
        await fs.mkdir(path.dirname(this.file), { recursive: true });
        const fh = await fs.open(this.file, "a");
        try {
          await fh.write(JSON.stringify(event) + "\n");
          await fh.sync();
        } finally {
          await fh.close();
        }
      }
      events.push(event);
    };
    const next = this.chain.then(run, run);
    this.chain = next.catch(() => undefined);
    return next;
  }

  // ---- UpdateRepository (idempotent) ----
  async writeOnce(record: SavedUpdate): Promise<{ id: string; replayed: boolean }> {
    const existing = (await this.all()).find(
      (e) => e.type === "task_update" && e.record.idempotencyKey === record.idempotencyKey,
    );
    if (existing && existing.type === "task_update") return { id: existing.record.id, replayed: true };
    await this.append({ type: "task_update", at: record.at, record });
    return { id: record.id, replayed: false };
  }

  async read(id: string): Promise<SavedUpdate | null> {
    if (this.file) this.events = null; // force a fresh read from disk for read-back
    const hit = (await this.all()).find((e) => e.type === "task_update" && e.record.id === id);
    return hit && hit.type === "task_update" ? hit.record : null;
  }

  async latestUpdate(taskId: string): Promise<SavedUpdate | null> {
    const ups = (await this.all()).filter((e) => e.type === "task_update" && e.record.taskId === taskId);
    const last = ups[ups.length - 1];
    return last && last.type === "task_update" ? last.record : null;
  }

  async findCallByTokenHash(tokenHash: string): Promise<CallSession | null> {
    const hit = (await this.all()).find((e) => e.type === "call_session" && e.session.tokenHash === tokenHash);
    return hit && hit.type === "call_session" ? hit.session : null;
  }

  async since(iso: string): Promise<StoredEvent[]> {
    return (await this.all()).filter((e) => e.at > iso);
  }
}

import { randomBytes } from "node:crypto";
import type { EvidenceSnapshot, Task } from "../contracts";
import { resolveCaller, type Caller } from "../auth/call-session";
import { markAttempted } from "../core/communication-ledger";
import { persistVerifiedUpdate } from "../core/persist-update";
import { short } from "../core/reconcile";
import type { Specialist } from "../core/spatial-specialists";
import type { EventStore } from "../store/event-store";
import { evidenceVerifier } from "../specialists/evidence-verifier";
import { handleTurn, startConversation, type Conversation } from "../specialists/orchestrator";

// The four runtime tools Bolna calls during a phone call (D-013). Framework-free:
// app/api/tools/[tool]/route.ts is a thin HTTP wrapper around these.

export interface Runtime {
  store: EventStore;
  snapshot: EvidenceSnapshot;
  conversations: Map<string, Conversation>;
}

export type ToolResponse = { status: number; body: Record<string, unknown> };
export const TOOL_NAMES = ["get_my_brief", "get_task_evidence", "get_changes", "record_task_update"] as const;
export type ToolName = (typeof TOOL_NAMES)[number];

export async function runTool(rt: Runtime, tool: ToolName, body: Record<string, unknown>): Promise<ToolResponse> {
  const auth = await resolveCaller(rt.store, rt.snapshot, body.call_token ?? body.callToken);
  if (!auth.ok) return { status: auth.status, body: { ok: false, error: auth.reason, speak: "I can't verify who I'm speaking with, so I can't share project details." } };
  const caller = auth.caller;
  const res = await dispatch(rt, tool, caller, body);
  await rt.store.append({
    type: "tool_call",
    at: new Date().toISOString(),
    callId: caller.session.callId,
    tool,
    ok: res.status < 400 && res.body.ok !== false,
    summary: String(res.body.speak ?? res.body.error ?? "").slice(0, 300),
    evidenceIds: (res.body.evidenceIds as string[] | undefined) ?? [],
  });
  return res;
}

function pickTask(rt: Runtime, caller: Caller, requested?: unknown): Task | undefined {
  const mine = rt.snapshot.tasks.filter((t) => caller.taskIds.has(t.id));
  if (typeof requested === "string" && requested) return mine.find((t) => t.id === requested); // never another person's task
  const conv = rt.conversations.get(caller.session.callId);
  return mine.find((t) => t.id === conv?.focus.taskId) ?? mine.find((t) => t.assignment.state === "accepted") ?? mine[0];
}

async function dispatch(rt: Runtime, tool: ToolName, caller: Caller, body: Record<string, unknown>): Promise<ToolResponse> {
  const callId = caller.session.callId;
  switch (tool) {
    case "get_my_brief": {
      const task = pickTask(rt, caller);
      if (!task) return ok({ speak: `Hi ${caller.participant.name}. I don't see any task from the approved meeting assigned to you.`, tasks: [] });
      const meeting = rt.snapshot.meetings.find((m) => m.id === task.meetingId);
      const passage = rt.snapshot.passages.find((p) => task.passageIds.includes(p.id));
      const v = evidenceVerifier(rt.snapshot, task, await rt.store.latestUpdate(task.id));
      const facts = [
        { id: "decision", fact: `In "${meeting?.title ?? "the meeting"}", the team agreed: ${task.title}.` },
        { id: "status", fact: v.statements[0] ?? "There's no code evidence yet." },
        { id: "next", fact: v.statements.slice(1, 3).join(" ") || "Next step: open the code and confirm it does what the meeting said." },
      ];
      let conv = startConversation(callId, caller.participant.id, task.id, facts);
      conv.ledger = markAttempted(markAttempted(conv.ledger, "decision"), "status");
      conv.lastSpokenFactIds = ["decision", "status"];
      conv.cards.evidence_verifier = { ...conv.cards.evidence_verifier, status: "has_reply", summary: v.statements.join(" ") };
      rt.conversations.set(callId, conv);
      return ok({
        speak: `Hi ${caller.participant.name}. ${facts[0].fact} ${facts[1].fact} Want me to show you exactly where the code is?`,
        task: { id: task.id, title: task.title, ownership: v.reconciled.ownership, pr: v.reconciled.pr, checks: v.reconciled.checks, sha: short(v.reconciled.currentSha) },
        source: { meetingId: task.meetingId, passageId: passage?.id, speaker: passage?.speaker, label: rt.snapshot.label },
        pending: ["next"],
        evidenceIds: [...task.passageIds, ...(v.reconciled.prNumber ? [`pr:${v.reconciled.prNumber}`] : [])],
      });
    }
    case "get_task_evidence": {
      const task = pickTask(rt, caller, body.task_id ?? body.taskId);
      if ((body.task_id ?? body.taskId) && !task) return { status: 403, body: { ok: false, error: "task not authorized", speak: "That task isn't one I can share with you." } };
      const conv = rt.conversations.get(callId) ?? startConversation(callId, caller.participant.id, task?.id ?? null, []);
      const focus = parseFocus(body.focus);
      const utterance = String(body.question ?? body.utterance ?? "");
      const r = handleTurn(conv, rt.snapshot, task, task ? await rt.store.latestUpdate(task.id) : null, { utterance, focus });
      rt.conversations.set(callId, r.conversation);
      const card = r.conversation.cards[r.specialist];
      return ok({
        speak: r.spoken,
        specialist: r.specialist,
        taskId: r.conversation.focus.taskId,
        contextVersion: r.conversation.focus.contextVersion,
        steps: r.navigation?.steps,
        evidence: card.evidence,
        evidenceIds: card.evidence.map((e) => e.id),
        snapshot: { label: rt.snapshot.label, repository: rt.snapshot.repository, pinnedSha: rt.snapshot.pinnedSha },
      });
    }
    case "get_changes": {
      const since = typeof body.since === "string" ? body.since : new Date(Date.now() - 24 * 3600_000).toISOString();
      const events = (await rt.store.all()).filter((e) => e.type === "task_update" && caller.taskIds.has(e.record.taskId));
      const changes = events
        .map((e, i) => ({ e, prev: events.slice(0, i).reverse().find((p) => p.type === "task_update" && e.type === "task_update" && p.record.taskId === e.record.taskId) }))
        .filter(({ e }) => e.at > since)
        .map(({ e, prev }) => e.type === "task_update" && ({
          taskId: e.record.taskId, status: e.record.status, previous: prev?.type === "task_update" ? prev.record.status : "none", at: e.at, recordId: e.record.id,
        }))
        .filter(Boolean);
      return ok({
        speak: changes.length ? `${changes.length} update${changes.length > 1 ? "s" : ""} since then.` : "Nothing has changed on your tasks since then.",
        since, changes, snapshotFetchedAt: rt.snapshot.fetchedAt, evidenceIds: [],
      });
    }
    case "record_task_update": {
      const blocked = new Map<string, string>();
      for (const t of rt.snapshot.tasks) {
        if (t.assignment.state === "disputed" || t.assignment.state === "unknown") blocked.set(t.id, "ownership is not established, so I won't record a status");
        else if (t.assignment.state === "accepted" && t.assignment.ownerId && t.assignment.ownerId !== caller.participant.id) blocked.set(t.id, "this task belongs to someone else");
      }
      const raw = { ...body, taskId: body.task_id ?? body.taskId ?? pickTask(rt, caller)?.id };
      const result = await persistVerifiedUpdate({
        raw, trustedActorId: caller.participant.id, callId, authorizedTaskIds: caller.taskIds, blockedTaskIds: blocked,
        repository: rt.store, generateId: () => `upd_${randomBytes(6).toString("hex")}`,
      });
      const conv = rt.conversations.get(callId);
      if (!result.saved) {
        if (conv) conv.cards.evidence_verifier = { ...conv.cards.evidence_verifier, status: "error", summary: `Not saved: ${result.reason}` };
        return { status: 409, body: { ok: false, saved: false, reason: result.reason, speak: `I couldn't save that — ${result.reason}. Nothing was changed.` } };
      }
      if (conv) {
        conv.focus = { ...conv.focus, contextVersion: conv.focus.contextVersion + 1 };
        conv.cards.evidence_verifier = { ...conv.cards.evidence_verifier, status: "has_reply", summary: `Saved and read back: ${result.readBack.status} (${result.recordId}).`,
          evidence: [...conv.cards.evidence_verifier.evidence.filter((e) => !e.id.startsWith("upd_")), { id: result.recordId, label: `saved: ${result.readBack.status} · read back` }] };
      }
      return ok({
        saved: true, recordId: result.recordId, replayed: result.replayed, readBack: result.readBack,
        speak: `Saved. I marked it ${result.readBack.status.replace("_", " ")} and read it back from the store.`,
        evidenceIds: [result.recordId],
      });
    }
  }
}

const ok = (body: Record<string, unknown>): ToolResponse => ({ status: 200, body: { ok: true, ...body } });
const FOCI: Record<string, Specialist> = { find: "code_scout", code_scout: "code_scout", locate: "fix_navigator", fix_navigator: "fix_navigator", verify: "evidence_verifier", evidence_verifier: "evidence_verifier" };
const parseFocus = (f: unknown): Specialist | undefined => (typeof f === "string" ? FOCI[f] : undefined);

import type { CompletionStatus, TaskUpdateRequest } from "./contracts";

const STATUSES: readonly CompletionStatus[] = ["not_started", "in_progress", "blocked", "reported_done"];

export type Parsed<T> = { ok: true; value: T } | { ok: false; reason: string };

export function parseTaskUpdate(raw: unknown): Parsed<TaskUpdateRequest> {
  if (!raw || typeof raw !== "object") return { ok: false, reason: "body must be an object" };
  const r = raw as Record<string, unknown>;
  const taskId = r.taskId ?? r.task_id;
  const status = r.intendedStatus ?? r.status;
  const key = r.idempotencyKey ?? r.idempotency_key;
  const confirmation = r.confirmation ?? r.confirmed;
  if (typeof taskId !== "string" || !taskId) return { ok: false, reason: "taskId required" };
  if (typeof status !== "string" || !STATUSES.includes(status as CompletionStatus))
    return { ok: false, reason: `status must be one of ${STATUSES.join(", ")}` };
  if (confirmation !== true && confirmation !== "true") return { ok: false, reason: "caller has not confirmed" };
  if (typeof key !== "string" || key.length < 8) return { ok: false, reason: "idempotencyKey (8+ chars) required" };
  return { ok: true, value: { taskId, intendedStatus: status as CompletionStatus, confirmation: true, idempotencyKey: key } };
}

